export function canMake(word: string, counts: readonly number[]): boolean {
  const left = counts.slice();
  for (const char of word) {
    const index = char.charCodeAt(0) - 97;
    if (index < 0 || index >= 26 || left[index] === 0) return false;
    left[index]--;
  }
  return true;
}
